'use strict';
const EcologyUI=(()=>{
 const origin={birth:'คลอดและพึ่งการดูแลของกลุ่ม',egg:'ฟักจากไข่',roe:'ฟักในน้ำ',bud:'แตกหน่อ',seed:'งอกจากเมล็ด',spore:'ก่อร่างจากสปอร์',awaken:'ตื่นรู้จากแกน',crystal:'ก่อรูปจากผลึก',ember:'ถือกำเนิดจากแกนเปลว',sand:'รวมรูปจากทราย',ink:'รวมร่างจากหมึก'};
 function birth(s){if(!s.race)return '';const p=Ecology.profile(s);return `<section class="ecology-birth"><span class="eyebrow">วิถีของ ${esc(RACES[s.race][0])}</span><h3>${esc(p.label)}</h3><dl><div><dt>การถือกำเนิด</dt><dd>${esc(origin[p.origin])}</dd></div><div><dt>การเรียนรู้</dt><dd>${esc(p.learningSkill)}</dd></div><div><dt>แหล่งดำรงชีวิต</dt><dd>${esc(p.food)}</dd></div></dl><p>โตเต็มวัยราว ${Species.maturity(s.race)} ปี · ${esc(p.early)}</p></section>`}
 function panel(s){if(!s.race)return '';const p=Ecology.profile(s);return `<button class="panel ecology-strip" id="ecologyProfile"><span class="ecology-mark" aria-hidden="true">⌁</span><span><small>ถิ่นพักและวิถีชีวิต</small><strong>${esc(p.label)}</strong><span>${esc(LifeGrowth.stage(s).name)} · ${esc(p.learning)}</span></span><b aria-hidden="true">↗</b></button>`}
 function bind(){const b=$('#ecologyProfile');if(b)b.onclick=open}
 function open(){const s=state,p=Ecology.profile(s),mode=Ecology.ensure(s).mode,locked=s.dead||!s.accepted||s.calendar?.pending||s.outcome||Engine.biological(s)<18;modal(`<div class="life-dialog"><span class="eyebrow">${esc(RACES[s.race][0])} · อายุ ${s.age} ปี</span><h2>${esc(p.label)}</h2>${birth(s)}<p>${esc(p.routine)}</p><p>สิ่งที่คุณรับรู้ได้: ${esc(p.sense)}</p>${p.strict?`<h3>วิถีการดำรงชีวิต</h3><div class="choices"><button class="choice" data-ecology-mode="native" ${locked||mode==='native'?'disabled':''}><span>${mode==='native'?'✓':'⌁'}</span><span><b>อยู่ตามวิถีของถิ่น</b><small>หาแหล่งดำรงชีวิตร่วมกับกลุ่ม ไม่เสียค่าเช่าบ้านในเมือง</small></span></button><button class="choice" data-ecology-mode="exchange" ${locked||mode==='exchange'?'disabled':''}><span>${mode==='exchange'?'✓':'⌁'}</span><span><b>ร่วมงานกับชุมชนต่างเผ่า</b><small>เปิดเส้นทางงานเวท สื่อสาร และนำทางที่ร่างทำได้ · มีค่าเสบียงและบริการจากชุมชน</small></span></button></div>`:''}</div>`);document.querySelectorAll('[data-ecology-mode]').forEach(b=>b.onclick=()=>{if(Ecology.chooseMode(s,b.dataset.ecologyMode)){save();clock.reset();render();open()}})}
 return {birth,panel,bind,open};
})();
